import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import readline from 'node:readline';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};


 const out='/tmp/legendgirl-manual';await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/manual',{recursive:true});
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});
 for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='EASY';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));})()`);
 for(let i=0;i<200;i++){if(await evaluate('Boolean(game.state.toyRoomInstance?.instance?.garden?.ready)'))break;await new Promise(r=>setTimeout(r,50));}
 await evaluate(`(async()=>{
  game.setPaused(true);const phase=game.state.toyRoomInstance.instance.garden;
  const {createGardenState,restoreGardenState}=await import('/src/js/garden/GardenSimulation.js'),{GARDEN_PLATFORM_BY_ID:map,GARDEN_SECTIONS:sections,gardenSurfaceY}=await import('/src/js/garden/GardenLevel.js'),{gardenContactHeight}=await import('/src/js/garden/GardenContact.js');
  const checkpoint=sections.find(s=>s.id==='trecho-2').x+120,ground=[...map.values()].find(p=>p.ground&&checkpoint>=p.x&&checkpoint<p.x+p.w),s=createGardenState('EASY');s.stage='RUNNING';s.checkpoint=checkpoint;s.safeGround=ground.id;s.trail=[ground.id];Object.assign(s.player,{x:checkpoint,onGround:true,support:ground.id,terrain:ground.type});s.player.y=gardenContactHeight(ground,s.player);phase.state=restoreGardenState(s,'EASY');
  const r=phase.renderer,draw=r.render.bind(r),surface=r.groundSurface.bind(r),terrain=r.terrain.bind(r),front=r.grassFront.bind(r);
  window.manualQa={phase,mode:'otimizado',times:[],intervals:[],all:[],last:0};
  r.render=function(...args){const t=performance.now(),result=draw(...args);if(!game.isPaused())manualQa.times.push(performance.now()-t);return result;};
  requestAnimationFrame(function frame(t){if(!game.isPaused()){if(manualQa.last&&t-manualQa.last<150)manualQa.intervals.push(t-manualQa.last);manualQa.last=t;}else manualQa.last=0;requestAnimationFrame(frame);});
  r.groundSurface=function(ctx,p,l,right){
   if(manualQa.mode!=='anterior'||!p.hill)return surface(ctx,p,l,right);
   const tile=this.surfaceTile(p.type),start=p.patchX??p.x,width=p.patchWidth??p.w;
   for(let x=start;x<start+width;x+=4){const sw=Math.min(4,start+width-x),sx=((x%220)+220)%220;ctx.drawImage(tile,sx,0,Math.min(sw+.5,220-sx),tile.height,x,gardenSurfaceY(p,x+sw/2)-(p.type==='grass'?90:18),sw+.5,tile.height);}
  };
  r.terrain=function(ctx,p,...args){return terrain(ctx,manualQa.mode==='anterior'&&p.grassPatches?{...p,type:'grass',grassPatches:null}:p,...args);};
  r.grassFront=function(ctx,s,platforms){return front(ctx,s,manualQa.mode==='anterior'?platforms.map(p=>p.grassPatches?{...p,type:'grass',grassPatches:null}:p):platforms);};
 })()`);
 let count=0;const results=[];
 async function observe(){
  const state=await evaluate(`(()=>{const m=manualQa,s=m.phase.state,p=s.player,t=m.times.slice().sort((a,b)=>a-b),d=m.intervals.slice().sort((a,b)=>a-b);return{modo:m.mode,stage:s.stage,x:p.x,y:p.y,hp:s.hp,support:p.support,terrain:p.terrain,frames:t.length,renderMedio:t.reduce((a,b)=>a+b,0)/Math.max(1,t.length),renderP95:t[Math.floor(t.length*.95)]??0,quadroP95:d[Math.floor(d.length*.95)]??0};})()`);
  const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(out+'/atual.png',Buffer.from(shot.result.data,'base64'));await writeFile(out+'/estado.json',JSON.stringify(state));await writeFile('docs/diario-ia/qa-resultados/manual/quadro-'+count+'.png',Buffer.from(shot.result.data,'base64'));count++;return state;
 }
 await observe();console.log('PRONTO: checkpoint legítimo de QA; ações seguintes somente por eventos reais de teclado e RAF.');
 for await(const line of readline.createInterface({input:process.stdin,crlfDelay:Infinity})){
  let command;try{command=JSON.parse(line);}catch{continue;}
  if(command.finish)break;
  if(command.mode)await evaluate(`manualQa.mode=${JSON.stringify(command.mode)};manualQa.times=[];manualQa.intervals=[];manualQa.last=0;`);
  await evaluate('game.setPaused(false)');
  for(const code of command.keys??[])await call('Input.dispatchKeyEvent',{type:'keyDown',code,key:code==='Space'?' ':code});
  await new Promise(r=>setTimeout(r,Math.min(5000,command.ms??300)));
  for(const code of command.keys??[])await call('Input.dispatchKeyEvent',{type:'keyUp',code,key:code==='Space'?' ':code});
  await evaluate('game.setPaused(true)');const result=await observe();results.push({comando:command,...result});
 }
 process.stdin.pause();process.stdin.unref?.();
 await writeFile('docs/diario-ia/qa-resultados/manual/resultado.json',JSON.stringify({metodo:'Gameplay da IA por eventos reais de teclado no host e RAF em tempo real; carregamento inicial de checkpoint de QA, sem teleporte durante os segmentos. Comparação anterior é fixture gráfica do desenho em tiras/cobertura integral; física idêntica.',resultados:results},null,2));console.log(JSON.stringify(results));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
